INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Einrichtung IT-Arbeitsplätze > Arbeitssicherheit & Gesundheitsschutz
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Einrichtung von IT-Arbeitsplätzen immer gesetzliche Vorschriften zur Arbeitssicherheit beachtet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzliche Vorgaben wie Arbeitsschutzgesetz sind bindend"}, {"text": "Nein", "correct": false, "because": "Pflicht zur Einhaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Gesundheitsschutz an IT-Arbeitsplätzen ohne ergonomische Maßnahmen gewährleistet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Ergonomie schützt vor gesundheitlichen Schäden"}, {"text": "Ja", "correct": false, "because": "Ergonomie ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Beleuchtung am IT-Arbeitsplatz ein relevanter Faktor für die Arbeitssicherheit?', 2, '[{"text": "Ja", "correct": true, "because": "Gute Beleuchtung verhindert Augenbelastung"}, {"text": "Nein", "correct": false, "because": "Beleuchtung ist wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IT-Arbeitsplätze ohne Rücksicht auf Lärmschutz eingerichtet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Lärm kann Gesundheit beeinträchtigen"}, {"text": "Ja", "correct": false, "because": "Lärmschutz ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Arbeitssicherheitsmaßnahmen an IT-Arbeitsplätzen nur für große Unternehmen verpflichtend?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Unternehmensgrößen"}, {"text": "Ja", "correct": false, "because": "Universell vorgeschrieben"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist bei der Arbeitssicherheit an IT-Arbeitsplätzen am wichtigsten?', 3, '[{"text": "Ergonomie", "correct": true, "because": "Verhindert körperliche Schäden"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Ästhetisch, nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme schützt die Gesundheit an IT-Arbeitsplätzen?', 2, '[{"text": "Ergonomischer Stuhl", "correct": true, "because": "Unterstützt Haltung"}, {"text": "Laute Musik", "correct": false, "because": "Beeinträchtigt Konzentration"}, {"text": "Schwere Tische", "correct": false, "because": "Nicht gesundheitsfördernd"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage regelt die Arbeitssicherheit an IT-Arbeitsplätzen in Deutschland?', 2, '[{"text": "Arbeitsschutzgesetz", "correct": true, "because": "Regelt Sicherheitsstandards"}, {"text": "Datenschutzgesetz", "correct": false, "because": "Datenschutz, nicht Sicherheit"}, {"text": "Urheberrechtsgesetz", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor trägt zum Gesundheitsschutz an IT-Arbeitsplätzen bei?', 3, '[{"text": "Bildschirmhöhe", "correct": true, "because": "Verhindert Nackenprobleme"}, {"text": "Monitorfarbe", "correct": false, "because": "Ästhetisch"}, {"text": "Kabellänge", "correct": false, "because": "Funktional, nicht gesundheitlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel des Gesundheitsschutzes an IT-Arbeitsplätzen?', 2, '[{"text": "Vermeidung von Belastungen", "correct": true, "because": "Schützt vor Schäden"}, {"text": "Maximierung der Kosten", "correct": false, "because": "Nicht Ziel"}, {"text": "Schnelle Installation", "correct": false, "because": "Sekundär"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fördern die Arbeitssicherheit an IT-Arbeitsplätzen?', 4, '[{"text": "Ergonomische Möbel", "correct": true, "because": "Schützen Körperlich"}, {"text": "Gute Beleuchtung", "correct": true, "because": "Schont Augen"}, {"text": "Lärmschutz", "correct": true, "because": "Reduziert Stress"}, {"text": "Hohe Raumtemperatur", "correct": false, "because": "Ungeeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesundheitlichen Risiken bestehen an IT-Arbeitsplätzen?', 3, '[{"text": "Rückenprobleme", "correct": true, "because": "Durch schlechte Haltung"}, {"text": "Augenbelastung", "correct": true, "because": "Durch Bildschirmarbeit"}, {"text": "Stress durch Lärm", "correct": true, "because": "Beeinträchtigt Wohlbefinden"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorschriften regeln Arbeitssicherheit und Gesundheitsschutz?', 3, '[{"text": "Arbeitsschutzgesetz", "correct": true, "because": "Grundlage"}, {"text": "Bildschirmarbeitsverordnung", "correct": true, "because": "Spezifisch für IT"}, {"text": "Technische Regeln", "correct": true, "because": "Praktische Umsetzung"}, {"text": "Datenschutzverordnung", "correct": false, "because": "Datenschutz, nicht Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente tragen zur Ergonomie an IT-Arbeitsplätzen bei?', 4, '[{"text": "Höhenverstellbarer Stuhl", "correct": true, "because": "Passt Haltung an"}, {"text": "Bildschirmposition", "correct": true, "because": "Schont Augen und Nacken"}, {"text": "Tastaturwinkel", "correct": true, "because": "Verhindert Handgelenkschäden"}, {"text": "Kabelfarbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen schützen die Gesundheit an IT-Arbeitsplätzen?', 3, '[{"text": "Pausenregelung", "correct": true, "because": "Verhindert Überanstrengung"}, {"text": "Bildschirmfilter", "correct": true, "because": "Reduziert Blaulicht"}, {"text": "Klimatisierung", "correct": true, "because": "Angenehme Temperatur"}, {"text": "Lautes Radio", "correct": false, "because": "Stört Konzentration"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ergonomische Möbel fördern die Gesundheit an IT-Arbeitsplätzen. b) Arbeitssicherheit ist nur für körperliche Arbeit relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergonomie ja, Sicherheit allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gute Beleuchtung schützt die Augen an IT-Arbeitsplätzen. b) Lärmschutz ist irrelevant für die Gesundheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beleuchtung ja, Lärmschutz wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Arbeitsschutzgesetz gilt für IT-Arbeitsplätze. b) Ergonomie ist nur für große Unternehmen wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gesetz ja, Ergonomie allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Bildschirmhöhe beeinflusst die Gesundheit an IT-Arbeitsplätzen. b) Gesetzliche Vorschriften sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Höhe ja, Vorschriften bindend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Pausenregelungen fördern die Gesundheit an IT-Arbeitsplätzen. b) Arbeitssicherheit betrifft nur neue Geräte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pausen ja, Sicherheit allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

